CREATE DATABASE IF NOT EXISTS nexa_commerce CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexa_commerce;
CREATE TABLE businesses (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, business_type VARCHAR(60) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('ADMIN','EMPLEADO') DEFAULT 'EMPLEADO', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id));
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255), status ENUM('ACTIVA','INACTIVA') DEFAULT 'ACTIVA', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_category_business (business_id,name), FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, name VARCHAR(150) NOT NULL, document VARCHAR(60), phone VARCHAR(40), email VARCHAR(160), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE suppliers (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, name VARCHAR(150) NOT NULL, document VARCHAR(60), phone VARCHAR(40), email VARCHAR(160), address VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, category_id INT NULL, supplier_id INT NULL, name VARCHAR(150) NOT NULL, sku VARCHAR(80) NOT NULL, description TEXT, purchase_price DECIMAL(12,2) DEFAULT 0, sale_price DECIMAL(12,2) NOT NULL, stock INT DEFAULT 0, minimum_stock INT DEFAULT 0, status ENUM('ACTIVO','INACTIVO') DEFAULT 'ACTIVO', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_product_business_sku (business_id,sku), INDEX idx_product_search (business_id,name), FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL, FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL);
CREATE TABLE sales (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, user_id INT NOT NULL, customer_id INT NULL, total DECIMAL(12,2) NOT NULL, payment_method ENUM('EFECTIVO','TRANSFERENCIA','TARJETA','OTRO') DEFAULT 'EFECTIVO', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE sale_details (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE inventory_movements (id INT AUTO_INCREMENT PRIMARY KEY, business_id INT NOT NULL, product_id INT NOT NULL, user_id INT NOT NULL, type ENUM('ENTRADA','SALIDA','AJUSTE','VENTA') NOT NULL, quantity INT NOT NULL, previous_stock INT NOT NULL, new_stock INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (business_id) REFERENCES businesses(id), FOREIGN KEY (product_id) REFERENCES products(id), FOREIGN KEY (user_id) REFERENCES users(id));
